import{_ as a,o as n,c as t,a0 as i}from"./chunks/framework.BXmxXpv-.js";const h=JSON.parse('{"title":"","titleTemplate":"UESTC","description":"","frontmatter":{"layout":"home","titleTemplate":"UESTC","hero":{"name":"Intelligent Computing Systems\\nLaboratory","tagline":"Next-generation Intelligent Systems Exploration","image":{"src":"/nise-logo.svg","alt":"ICSLab"}}},"headers":[],"relativePath":"index.md","filePath":"en/index.md","lastUpdated":1783389629000}'),o={name:"index.md"};function s(r,e,l,c,d,m){return n(),t("div",null,[...e[0]||(e[0]=[i('<h2 id="about-us" tabindex="-1">About Us <a class="header-anchor" href="#about-us" aria-label="Permalink to &quot;About Us&quot;">​</a></h2><p>The Intelligent Computing Systems Laboratory is affiliated with the School of Computer Science and Engineering, University of Electronic Science and Technology of China (UESTC). Established in January 2018, the lab is dedicated to fundamental research and system development in areas including wireless systems and security, passive systems, RFID technology, network and system security, intelligent information processing, data mining and recommendation, and intelligent video analysis. We aim to focus on the frontier, lead the future, and explore new paradigms of deep integration between intelligent computing and the physical world, making key breakthroughs in core theories and critical technologies of embodied intelligence. Our team comprises 1 professor, 1 associate professor, and nearly 30 master&#39;s and doctoral students. Over the past five years, we have undertaken numerous projects funded by the National Natural Science Foundation of China, National Key R&amp;D Programs, and National Science and Technology Support Programs.</p><p>We have achieved numerous research outcomes in passive wireless sensing IoT systems, wireless embedded systems, and intelligent information processing. We have built a series of practical systems and application demonstrations for structural health monitoring, wearable medical devices, and wearable remote health monitoring. The team has published over 120 papers in prominent Transactions journals and top international academic conferences, such as ACM/IEEE. Our laboratory is equipped with comprehensive R&amp;D equipment, various system software, application software, and design/development tools, providing a complete R&amp;D chain from sensing front-end design, communication protocols and systems, intelligent information processing, cloud systems, to network security.</p><h2 id="main-research-areas" tabindex="-1">Main Research Areas <a class="header-anchor" href="#main-research-areas" aria-label="Permalink to &quot;Main Research Areas&quot;">​</a></h2><ul><li><strong>IoT Edge Architecture and Intelligent Computing</strong>: Lightweight edge intelligent algorithms and chip design for embodied intelligence, edge-cloud collaborative computing architecture and task offloading strategies, mobile analysis, and machine learning applications at the edge.</li><li><strong>Embodied Intelligent Sensing and Interaction</strong>: Intelligent perception of the physical world, cognitive mechanisms of image and visual information computing, passive wireless sensing systems.</li><li><strong>Swarm Collaborative Intelligence and Communication</strong>: Communication technologies for swarm collaboration, distributed intelligence and collaborative decision-making, wireless systems, and network security.</li><li><strong>Intelligent Information Processing and Applications</strong>: Data mining and recommendation systems, intelligent data analysis, prototype systems, and application demonstrations.</li></ul><h2 id="representative-research-projects" tabindex="-1">Representative Research Projects <a class="header-anchor" href="#representative-research-projects" aria-label="Permalink to &quot;Representative Research Projects&quot;">​</a></h2><ol><li><strong>National Natural Science Foundation of China</strong>, Safety-Critical Aviation Intelligent Manufacturing Threat Monitoring and Dynamic Adaptive Defense Research, 2022.01-2025.12, PI</li><li><strong>Industry Project</strong>, Research on Mechanism and Precision Resuscitation of Extracorporeal Cardiac Compression based on Dynamics, 2024.01-2025.10, PI</li><li><strong>National Natural Science Foundation of China (2021 &amp; beyond)</strong>, Research on Theory and Key Technologies of IoT Wireless Bus, 2026.01-2029.12, PI</li><li><strong>National Natural Science Foundation of China</strong>, Mechanism Research and Translation of Thrombosis-Inflammation Model in Early Diagnosis and Risk Stratification of Acute Aortic Dissection based on Multi-omics Temporal Graph Neural Network, 2023.01-2025.12, Participant</li><li><strong>National Key R&amp;D Program of China</strong>, Key Technologies for On-demand Desensitization and Evaluation of Privacy Data, 2021.12-2024.11, Participant</li><li><strong>National Natural Science Foundation of China</strong>, Cloud-Edge Integrated Distributed Large-scale Graph Data Stream Computing Methods, 2025.01-2028.12, PI</li></ol>',7)])])}const p=a(o,[["render",s]]);export{h as __pageData,p as default};
